import {APP_VERSION,RELEASES,unseenReleases,acknowledgeRelease} from './changelog.js';
import {setupUpdates,checkForUpdates} from './updates.js';
import {DIRS,currentNight,shiftDate,dateInZone,time,longDate,nightContext,analyze,fov,fitTarget,mosaicUseful,planetInfo,events,meteorEvents,clamp} from './astro.js';
import {SCOPES,load,save,storageIssue,restoreCheckpoint,rawStoredData,getScope,validTZ,sanitizeLocation,validate,exportData,mergeState,encodePayload,decodePayload,parseShared,sharePayload} from './store.js';
import {esc,curve,fovChart,skyChart,finderChart} from './charts.js';
import {weather,nightRows,summary,forecast} from './weather.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let state=load(),date=currentNight(state.location.tz),catalog=[],stars=[],constellations=[],ctx,results=[],view='tonight',weatherData=null,weatherError='',weatherLoading=false,weatherKey='',generation=0;
let filters={q:'',group:'Alle',direction:'',catalogue:'',sort:'score',mosaic:false,easy:false,wish:false,captured:false,onlyVisible:true,impact:0},limit=36,eventCache=null,dialogTarget=null,searchSequence=0,sessionRange=[0,1];
const skyNames=['Dunkler Himmel','Land','Vorstadt','Stadt'];
function persist(){try{save(state);}catch{toast('Speicher voll oder blockiert. Bitte sichere deine Daten.');}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function dialog(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal();$('#dialog').scrollTop=0;}
function close(){dialogTarget=null;$('#dialog').close();}
function scopes(){return state.scopes.map(id=>getScope(state,id));}
function scopeOptions(selected=state.scope){return scopes().map(s=>`<option value="${esc(s.id)}" ${selected===s.id?'selected':''}>${esc(s.name)}</option>`).join('');}
function grade(score){return score>=75?'good':score>=45?'warn':'bad';}
function duration(h){return `${Math.floor(h)} h ${String(Math.round((h%1)*60)).padStart(2,'0')} min`;}
function phaseName(){const n=ctx.phase;return n<12||n>348?'Neumond':n<78?'Zunehmende Sichel':n<102?'Erstes Viertel':n<168?'Zunehmender Mond':n<192?'Vollmond':n<258?'Abnehmender Mond':n<282?'Letztes Viertel':'Abnehmende Sichel';}
function signed(n){return n>=0?'+'+n:n;}
function temp(n){return n===null||n===undefined?'—':Math.round(state.units==='imperial'?n*1.8+32:n)+'°'+(state.units==='imperial'?'F':'C');}
function wind(n){return n===null||n===undefined?'—':Math.round(state.units==='imperial'?n/1.609:n)+(state.units==='imperial'?' mph':' km/h');}
function applyTheme(){document.documentElement.classList.toggle('redlight',state.redlight);document.documentElement.style.fontSize=`${16*state.textSize/100}px`;$('#night-mode').setAttribute('aria-label',state.redlight?'Rotlichtmodus ausschalten':'Rotlichtmodus einschalten');$('#night-mode').setAttribute('aria-pressed',String(state.redlight));}
function updateChrome(){applyTheme();$('#location-button').textContent='⌖ '+state.location.name;$('#connection').textContent=navigator.onLine?'Lokal gespeichert':'Offline';$('#plan-count').textContent=state.plan.length||'';$$('.bottom-nav a').forEach(a=>{if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
function recalc(){ctx=nightContext(date,state.location);const scope=getScope(state);results=catalog.map(t=>analyze(t,ctx,scope,{...state,windowStart:sessionRange[0],windowEnd:sessionRange[1]})).sort((a,b)=>b.score-a.score);eventCache=null;}
function titleBlock(title,sub,eyebrow='DEINE BEOBACHTUNGSNACHT'){return `<div class="page-head"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${sub}</p></div><div class="date-tools"><button data-act="prev-date" class="icon-button" aria-label="Vorherige Nacht">‹</button><input id="night-date" aria-label="Datum der Beobachtungsnacht" type="date" min="1900-01-01" max="2100-12-31" value="${date}"><button data-act="next-date" class="icon-button" aria-label="Nächste Nacht">›</button><button data-act="today" class="ghost">Heute</button></div></div>`;}
function nightLabel(){return new Intl.DateTimeFormat('de-DE',{day:'numeric',month:'long',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'))+' → '+new Intl.DateTimeFormat('de-DE',{day:'numeric',month:'long',timeZone:'UTC'}).format(new Date(shiftDate(date,1)+'T12:00:00Z'));}
function render(){updateChrome();if(view==='tonight')renderTonight();if(view==='explore')renderExplore();if(view==='plan')renderPlan();if(view==='settings')renderSettings();bindMain();}
function nightSummary(){const dark=ctx.sunTimes.darkStart&&ctx.sunTimes.darkEnd?`${time(ctx.sunTimes.darkStart,state.location.tz)}–${time(ctx.sunTimes.darkEnd,state.location.tz)}`:ctx.threshold===-18?'Durchgehend dunkel':ctx.dark.length?`${time(ctx.dark[0].d,state.location.tz)}–${time(ctx.dark.at(-1).d,state.location.tz)}`:'Keine dunklen Stunden';return `<section class="panel night-panel"><div class="panel-heading"><h2>Dein Nachtfenster</h2><span class="pill ${ctx.threshold===-18?'good':'warn'}">${ctx.threshold===-18?'Astronomische Nacht':ctx.threshold===-12?'Nautische Dämmerung':ctx.threshold===-6?'Bürgerliche Dämmerung':'Helle Nacht'}</span></div><p class="muted">${esc(nightLabel())} · ${esc(state.location.tz)}</p><div class="stats"><div class="stat"><strong>${ctx.darkHours.toFixed(1).replace('.',',')} h</strong><span>${ctx.threshold===-18?'Dunkelheit':'Dämmerungsfenster'}</span></div><div class="stat"><strong>${Math.round(ctx.illum*100)} %</strong><span>Mond beleuchtet</span></div><div class="stat"><strong>${ctx.moonFree.toFixed(1).replace('.',',')} h</strong><span>Mond unter Horizont</span></div></div><div class="timeline" role="img" aria-label="Tagesverlauf: Gold Tageslicht, Blau Dämmerung, Mint mondfreie Dunkelheit, Graublau Mond am Himmel">${ctx.samples.filter((s,i)=>i%3===0).map(s=>`<i class="${s.sun>=0?'day':s.sun<ctx.threshold?s.moon.altitude>0?'moon':'dark':''}"></i>`).join('')}</div><div class="timeline-legend"><span>12:00</span><span>18:00</span><span>00:00</span><span>06:00</span><span>12:00</span></div><div class="row spread space-top"><div><strong>${dark}</strong><div><small>${phaseName()}</small></div></div><button data-act="night-details" class="ghost">Details →</button></div></section>`;}
function weatherCard(){const rows=nightRows(weatherData,ctx),s=summary(rows);if(!s)return `<section class="panel"><div class="panel-heading"><h2>Wetter in der Nacht</h2><span class="pill">${weatherLoading?'Wird geladen':'Keine Prognose'}</span></div><p class="muted">${weatherLoading?'Stündliche Bewölkung, Taupunkt, Wind und Regen werden abgerufen.':esc(weatherError||'Für dieses Datum liegen keine Wetterdaten vor. Himmelspositionen und Pläne sind trotzdem verfügbar.')}</p><button data-act="weather-refresh">${weatherLoading?'Abruf läuft …':'Erneut laden'}</button><p class="statusline">Open-Meteo · nur die dunklen Stunden</p></section>`;return `<section class="panel"><div class="panel-heading"><h2>Wetter in der Nacht</h2><span class="pill ${weatherData.stale?'warn':grade(s.score)}">${weatherData.stale?'Gespeicherte Prognose':s.label}</span></div><div class="stats"><div class="stat"><strong>${s.cloud} %</strong><span>Wolken Ø</span></div><div class="stat"><strong>${s.clear} h</strong><span>Gute Chancen</span></div><div class="stat"><strong>${temp(s.best.temperature_2m)}</strong><span>Um ${time(s.best.d,state.location.tz)}</span></div></div><p class="muted">${s.score>=75?'Die Prognose bietet brauchbare Aufnahmefenster.':s.score>=45?'Plane flexibel: Zwischen den Wolken können sich Lücken öffnen.':'Die Bedingungen schränken längere Aufnahmen deutlich ein.'}</p><div class="row spread"><small>Stand ${longDate(weatherData.at,state.location.tz)}, ${time(weatherData.at,state.location.tz)}</small><button data-act="weather-details" class="ghost">Stunden →</button></div>${weatherData.stale?'<div class="notice">Abruf fehlgeschlagen. Diese Werte sind veraltet und keine aktuelle Vorhersage.</div>':''}</section>`;}
function card(t){const planned=state.plan.some(p=>p.id===t.id&&p.scope===state.scope);return `<article class="target-card"><button class="target-main" data-target="${esc(t.id)}" aria-label="${esc(t.name)} – Details öffnen"><div class="target-top"><span class="object-type">${esc(t.group)} · ${esc(t.constellation)}</span><span class="score"><strong>${t.score}</strong><small>/ 100</small></span></div><div class="designation">${esc(t.id)}${t.caldwell?' · C'+t.caldwell:''}${state.wish.includes(t.id)?' · ♡':''}${state.captured[t.id]?' · ✓':''}</div><h3>${esc(t.name===t.id?t.alias:t.name)}</h3><p class="target-meta">${t.hours?duration(t.hours)+' nutzbar':'Heute kein freies Fenster'} · ${Math.round(t.peak.alt)}° ${t.dir}</p>${curve(t,ctx)}<div class="row spread"><span class="pill ${t.fit.ratio>=1&&t.fit.ratio<12?'good':'warn'}">${t.fit.label}</span><small>Höchster Stand ${time(t.peak.d,state.location.tz)}</small></div></button><div class="card-footer"><span>${t.windows.length?`${time(t.windows[0].start,state.location.tz)}–${time(t.windows.at(-1).end,state.location.tz)}`:'Unter deinem Horizont'}</span><button data-add="${esc(t.id)}" aria-label="${planned?'Aus Plan entfernen':'Zum Plan hinzufügen'}: ${esc(t.name)}">${planned?'✓ Geplant':'+ Planen'}</button></div></article>`;}
function renderTonight(){const top=results.filter(t=>t.hours>=.5&&(!state.hideCaptured||!state.captured[t.id])).slice(0,6);$('#main').innerHTML=titleBlock('Deine Nacht im Blick.',`${esc(state.location.name)} · ${skyNames[state.sky]} · ${esc(getScope(state).name)}`)+(!state.onboarded?`<div class="callout"><div><h3>Bereit für deinen Himmel?</h3><p>Standort, Teleskop und freie Sicht anpassen.</p></div><button data-act="setup" class="primary">Einrichten</button></div>`:'')+`<div class="overview">${nightSummary()}<div id="weather-card">${weatherCard()}</div></div><div class="row spread wrap"><label class="field">Aktives Teleskop<select id="active-scope">${scopeOptions()}</select></label><div class="tool-row"><button data-act="session-window">◷ Aufnahmezeit</button><button data-act="sky-chart">⌖ Himmelskarte</button><button data-act="share-plan">↗ Nacht teilen</button></div></div><div class="section-head"><div><h2>Deine besten Ziele</h2><span class="muted">Sichtbarkeit, Mond & Bildfeld · Wetter separat</span></div><button data-act="all-targets">Alle ansehen →</button></div><div class="target-grid">${top.length?top.map(card).join(''):'<div class="empty"><h2>Heute kein passendes Zeitfenster</h2><p>Prüfe Datum, Horizont und Mindesthöhe. Im Katalog findest du weiterhin alle Ziele.</p><button data-act="all-targets">Katalog öffnen</button></div>'}</div><div class="section-head"><h2>Die nächsten sieben Nächte</h2><button data-act="weather-refresh" aria-label="Wetter aktualisieren">↻ Aktualisieren</button></div><div id="week-forecast">${weekHTML()}</div><div class="section-head"><h2>Was am Himmel passiert</h2><button data-act="events">Kalender →</button></div><div class="event-list">${planetInfo(ctx).filter(p=>p.best?.altitude>10).sort((a,b)=>b.best.altitude-a.best.altitude).slice(0,4).map(p=>`<div class="event"><div class="event-date">${time(p.best.d,state.location.tz)}</div><div><h3>${p.name}</h3><p>${Math.round(p.best.altitude)}° Höhe · ${p.illum.mag.toFixed(1)} mag</p><small>Höchster Stand während Sonne &lt; −6°</small></div></div>`).join('')||'<p class="muted">Keine gut stehenden Planeten im Dämmerungsfenster.</p>'}</div><p class="footer-note">Berechnet für deinen Standort. Sichtfenster im 10-Minuten-Raster. Wetter ist eine Prognose, kein Versprechen.</p>`;}
function weekHTML(){if(!weatherData)return '<p class="muted">Die Wochenübersicht erscheint nach dem Wetterabruf.</p>';return `<div class="forecast">${forecast(weatherData,state.location).map(f=>`<button data-date="${f.date}" class="${date===f.date?'active':''}" aria-label="Nacht ${f.date}: ${f.summary?f.summary.label:'keine Prognose'}"><small>${new Intl.DateTimeFormat('de-DE',{weekday:'short',timeZone:'UTC'}).format(new Date(f.date+'T12:00:00Z'))}</small><strong>${f.summary?f.summary.cloud+'%':'—'}</strong><small>${f.summary?f.summary.clear+' h gut':'Keine Daten'}</small></button>`).join('')}</div><p class="statusline">Mittlere Bewölkung während der Dunkelheit · ${weatherData.stale?'Veraltete Werte':'Open-Meteo'} · Tippe auf eine Nacht.</p>`;}
function filtered(){let r=results.filter(t=>(!filters.onlyVisible||t.hours>0)&&(!state.hideCaptured||filters.captured||!state.captured[t.id])&&(filters.group==='Alle'||t.group===filters.group)&&(!filters.direction||t.dir===filters.direction)&&(!filters.mosaic||mosaicUseful(t,getScope(state)))&&(!filters.easy||t.easy)&&(!filters.wish||state.wish.includes(t.id))&&(!filters.captured||state.captured[t.id])&&t.score>=filters.impact);const q=filters.q.toLocaleLowerCase().replaceAll(/\s/g,'');if(q)r=r.filter(t=>[t.name,t.id,t.alias,t.constellation,t.group,t.type,t.caldwell?'C'+t.caldwell:''].some(s=>String(s).toLocaleLowerCase().replaceAll(/\s/g,'').includes(q)));if(filters.catalogue==='Messier')r=r.filter(t=>/^M\d+$/.test(t.id));if(filters.catalogue==='Caldwell')r=r.filter(t=>t.caldwell);if(filters.catalogue==='Andere')r=r.filter(t=>!/^M\d+$/.test(t.id));return r.sort((a,b)=>filters.sort==='size'?(b.major||0)-(a.major||0):filters.sort==='timing'?a.peak.d-b.peak.d:filters.sort==='name'?a.id.localeCompare(b.id,undefined,{numeric:true}):b.score-a.score);}
function renderExplore(){const list=filtered();$('#main').innerHTML=titleBlock('Ziele entdecken.',`${catalog.length} Deep-Sky-Ziele · ${esc(getScope(state).name)}`,'DER HIMMELSKATALOG')+`<div class="filters-grid"><label class="field">Suche<input id="search-targets" type="search" placeholder="Name, M 31, NGC, Sternbild …" value="${esc(filters.q)}" autocomplete="off"></label><label class="field">Teleskop<select id="active-scope">${scopeOptions()}</select></label><label class="field">Richtung<select id="filter-direction"><option value="">Alle Richtungen</option>${DIRS.map(d=>`<option ${filters.direction===d?'selected':''}>${d}</option>`).join('')}</select></label><label class="field">Sortierung<select id="filter-sort"><option value="score" ${filters.sort==='score'?'selected':''}>Beste Eignung</option><option value="timing" ${filters.sort==='timing'?'selected':''}>Höchster Stand</option><option value="size" ${filters.sort==='size'?'selected':''}>Größe</option><option value="name" ${filters.sort==='name'?'selected':''}>Katalognummer</option></select></label></div><div class="filter-bar">${['Alle','Nebel','Galaxie','Sternhaufen'].map(g=>`<button data-group="${g}" class="chip ${filters.group===g?'active':''}" aria-pressed="${filters.group===g}">${g==='Galaxie'?'Galaxien':g}</button>`).join('')}<button data-filter="mosaic" class="chip ${filters.mosaic?'active':''}" aria-pressed="${filters.mosaic}">▦ Mosaik sinnvoll</button><button data-filter="easy" class="chip ${filters.easy?'active':''}" aria-pressed="${filters.easy}">Einsteiger</button><button data-filter="wish" class="chip ${filters.wish?'active':''}" aria-pressed="${filters.wish}">♡ Merkliste</button><button data-filter="captured" class="chip ${filters.captured?'active':''}" aria-pressed="${filters.captured}">✓ Aufgenommen</button><button data-act="filters" class="chip">Weitere Filter</button></div>${filters.mosaic?`<p class="notice">Mosaik für <strong>${esc(getScope(state).name)}</strong>: Ziele, die nicht in ein Einzelbild passen oder weniger als 20 % Reserve am Bildrand lassen. Grundlage sind Kataloggröße und Sensorbildfeld bei günstiger Ausrichtung. Die tatsächliche Mosaik-Unterstützung und Feldrotation bitte in deiner Teleskop-App prüfen.</p>`:''}<div class="row spread space-top"><p class="muted" id="results-count">${list.length} passende Ziele</p><label class="row muted"><input id="only-visible" type="checkbox" ${filters.onlyVisible?'checked':''}> Heute sichtbar</label></div><div id="results-grid" class="target-grid">${list.slice(0,limit).map(card).join('')||emptyResults()}</div><div class="row space-top" id="more-results">${list.length>limit?'<button class="full-width" data-act="load-more">Weitere Ziele anzeigen</button>':''}</div>`;}
function emptyResults(){return '<div class="empty"><h2>Kein Ziel passt zu diesen Filtern.</h2><p>Versuche „Alle“, schalte „Heute sichtbar“ aus oder wähle eine andere Nacht.</p><button data-act="reset-filters">Filter zurücksetzen</button></div>';}
function updateResults(){const list=filtered();$('#results-count').textContent=`${list.length} passende Ziele`;$('#results-grid').innerHTML=list.slice(0,limit).map(card).join('')||emptyResults();$('#more-results').innerHTML=list.length>limit?'<button class="full-width" data-act="load-more">Weitere Ziele anzeigen</button>':'';}
function schedule(){const used={};return state.plan.map((p,index)=>{const raw=catalog.find(t=>t.id===p.id);if(!raw)return null;const target=p.scope===state.scope?results.find(t=>t.id===p.id):analyze(raw,ctx,getScope(state,p.scope),{...state,windowStart:sessionRange[0],windowEnd:sessionRange[1]});const earliest=used[p.scope]||+ctx.start,ms=p.minutes*6e4;let slot;for(const w of target.windows){const start=Math.max(+w.start,earliest);if(start+ms<=+w.end){slot={start:new Date(start),end:new Date(start+ms)};break;}}if(slot)used[p.scope]=+slot.end+5*6e4;return{...p,index,target,slot};}).filter(Boolean);}
function renderPlan(){const entries=schedule();$('#main').innerHTML=titleBlock('Dein Aufnahmeplan.',`${entries.length} Aufnahmen · pro Teleskop ohne Überschneidungen`,'DEIN AUFNAHMEPLAN')+`<div class="tool-row"><button data-act="auto-plan" class="primary">✦ Nacht vorschlagen</button><button data-act="share-plan">Plan teilen</button><button data-act="export-calendar">Kalender (.ics)</button></div><div class="panel space-top">${entries.length?entries.map(p=>`<div class="plan-item"><div class="slot">${p.slot?time(p.slot.start,state.location.tz):'—'}<br><small>${p.slot?time(p.slot.end,state.location.tz):'Kein Platz'}</small></div><div><button class="ghost" style="padding:0;min-height:0;text-align:left" data-target="${esc(p.id)}"><h3>${esc(p.target.name)}</h3></button><p>${esc(p.id)} · ${esc(getScope(state,p.scope).name)}</p><small>${p.slot?`${Math.round(p.target.peak.alt)}° maximal · ${p.target.fit.label}`:'Gewünschte Dauer passt in kein freies Sichtfenster.'}</small></div><div class="plan-controls"><select data-plan-scope="${p.index}" aria-label="Teleskop für ${esc(p.id)}">${scopeOptions(p.scope)}</select><input type="number" min="10" max="600" step="10" data-plan-duration="${p.index}" value="${p.minutes}" aria-label="Aufnahmedauer in Minuten für ${esc(p.id)}"></div><button class="icon-button" data-remove-plan="${p.index}" aria-label="${esc(p.id)} aus Plan entfernen">×</button></div>`).join(''):'<div class="empty"><h2>Dein Plan wartet auf Sterne.</h2><p>Wähle ein Ziel über „Planen“ oder lass dir eine Nacht vorschlagen.</p><button data-act="all-targets">Ziele entdecken</button></div>'}</div><p class="notice">Die Reihenfolge bestimmt den Ablauf. Zwischen Aufnahmen sind 5 Minuten eingeplant. Unterschiedliche Teleskope dürfen parallel arbeiten. Der Plan berücksichtigt Sichtfenster; prüfe zusätzlich Wetter, Akkus und Filter.</p>${entries.length?'<div class="tool-row"><button data-act="sort-plan">Nach günstigster Startzeit sortieren</button><button data-act="print-plan">Drucken / PDF</button></div>':''}<div class="section-head"><h2>Deine Merkliste</h2><span class="muted">${state.wish.length} Ziele</span></div><div class="target-grid">${results.filter(t=>state.wish.includes(t.id)).slice(0,12).map(card).join('')||'<p class="muted">Tippe in einem Zieldetail auf „Merken“.</p>'}</div>`;}
function renderSettings(){$('#main').innerHTML=`<div class="page-head"><div><p class="eyebrow">SO BEOBACHTEST DU</p><h1>Ganz dein Himmel.</h1><p>Alles bleibt auf diesem Gerät. Sichere deine Daten vor einem Gerätewechsel.</p></div></div><div class="settings-grid"><section class="panel"><h2>App aktualisieren</h2><p>Sternklar ${APP_VERSION} · Updates direkt prüfen und anschließend installieren. Deine gespeicherten Daten bleiben erhalten.</p><button class="primary" data-act="check-update">Nach Updates suchen</button><button data-act="changelog" class="space-top">Was ist neu? / Changelog</button><p class="muted">Schließe offene Eingaben vor dem Installieren ab.</p><a href="./update.html">Update-Assistent bei Problemen öffnen</a></section><section class="panel"><h2>Standort & Horizont</h2><p>${esc(state.location.name)}<br><small>${state.location.lat.toFixed(4)}°, ${state.location.lon.toFixed(4)}° · ${esc(state.location.tz)}</small></p><div class="tool-row"><button data-act="location">Standort ändern</button><button data-act="horizon">Horizont anpassen</button></div><div class="space-top"><label class="field">Himmelshelligkeit<select data-setting="sky">${skyNames.map((s,i)=>`<option value="${i}" ${state.sky===i?'selected':''}>${s}</option>`).join('')}</select></label><label class="field space-top">Mindesthöhe über Horizont<input type="number" min="0" max="85" data-setting="minAltitude" value="${state.minAltitude}"></label></div></section><section class="panel"><h2>Deine Teleskope</h2><p class="muted">Ausgewählte Geräte stehen im Plan und Sichtfeldvergleich bereit.</p>${SCOPES.map(s=>`<label class="check-row"><span>${s.name}<small> · ${s.aperture}/${s.focal} mm</small></span><input type="checkbox" data-scope-toggle="${s.id}" ${state.scopes.includes(s.id)?'checked':''}></label>`).join('')}${state.customScopes.map(s=>`<label class="check-row"><span>${esc(s.name)}</span><input type="checkbox" data-scope-toggle="${esc(s.id)}" ${state.scopes.includes(s.id)?'checked':''}></label>`).join('')}<button data-act="custom-scope" class="full-width space-top">+ Eigenes Setup</button></section><section class="panel"><h2>Aufnahmebedingungen</h2><label class="field">Filter für die Bewertung<select data-setting="filter"><option value="none" ${state.filter==='none'?'selected':''}>Breitband / kein Schmalbandfilter</option><option value="dual" ${state.filter==='dual'?'selected':''}>Dualband (Emissionsnebel)</option></select></label><label class="check-row"><span>Mond in Empfehlungen berücksichtigen</span><input type="checkbox" data-setting="moonAdapt" ${state.moonAdapt?'checked':''}></label><label class="check-row"><span>Bereits aufgenommene Ziele ausblenden</span><input type="checkbox" data-setting="hideCaptured" ${state.hideCaptured?'checked':''}></label><p class="notice">Die Punktzahl ist eine nachvollziehbare Planungshilfe aus Höhe, Dauer, Mond, Himmel und Bildfeld. Sie ist keine garantierte Bildqualität.</p></section><section class="panel"><h2>Anzeige & Home Screen</h2><label class="check-row"><span>Rotlichtmodus</span><input type="checkbox" data-setting="redlight" ${state.redlight?'checked':''}></label><label class="field">Schriftgröße<input type="range" min="85" max="140" step="5" value="${state.textSize}" data-setting="textSize"><small>${state.textSize} %</small></label><label class="field space-top">Einheiten<select data-setting="units"><option value="metric" ${state.units==='metric'?'selected':''}>°C · km/h · km</option><option value="imperial" ${state.units==='imperial'?'selected':''}>°F · mph · mi</option></select></label><p class="notice">Auf iPhone / iPad in Safari: Teilen → „Zum Home-Bildschirm“ → als Web-App öffnen. Danach startet Sternklar im eigenen Fenster.</p><button data-act="offline-status">Offline-Verfügbarkeit prüfen</button></section><section class="panel"><h2>Sichern & übertragen</h2><p>Vor einem bestätigten Update wird zusätzlich eine lokale Sicherung angelegt.</p><div class="tool-row"><button data-act="restore-update">Update-Sicherung wiederherstellen</button><button data-act="raw-export">Gespeicherte Originaldaten sichern</button></div><p class="muted">Standorte, Horizont, Geräte, Merkliste, Aufnahmen und Plan – ohne Konto.</p><div class="tool-row"><button data-act="export-data">Datei sichern</button><button data-act="import-data">Daten einlesen</button></div><div class="tool-row space-top"><button data-act="export-code">Übertragungscode</button><button data-act="offline-images">Gemerkte Bilder offline speichern</button></div><p id="offline-progress" class="statusline"></p></section><section class="panel help"><h2>Wissen, was dahintersteckt</h2><details><summary>Wie werden Ziele ausgewählt?</summary><p>Für jede Nacht prüfen wir im Abstand von zehn Minuten die Höhe und die Hindernisse am Standort. Dauer und Höhe erhöhen die Eignung. Mondlicht, heller Himmel und ein unpassendes Bildfeld reduzieren sie. Ein Dualbandfilter hilft bei Emissionsnebeln. Wetter wird separat angezeigt, damit eine schlechte Prognose keine Ziele versteckt.</p></details><details><summary>Was bedeuten die Bildfeldhinweise?</summary><p>Die Katalogausdehnung wird mit den beiden Sensorachsen verglichen. Die günstigere Orientierung gilt; die reale Kameradrehung und Feldrotation können weitere Reserven erfordern. „Sehr kleines Motiv“ heißt, dass Details im Gesamtbild klein bleiben. Ein Mosaik braucht mehrere Felder und mehr Aufnahmezeit.</p></details><details><summary>Wolken, Tau, Seeing?</summary><p>Wolken in drei Höhen, Windböen, Regenwahrscheinlichkeit und die Differenz zum Taupunkt liefern praktische Hinweise. Sichtweite ist kein Seeing-Messwert; ein präzises Seeing wird nicht vorgetäuscht. Wettermodelle können lokale Wolkenlücken nicht sicher vorhersagen.</p></details><details><summary>Woher kommen die Bilder?</summary><p>Die optionalen DSS2-Surveybilder kommen vom CDS. Sie dienen zur Orientierung; sie zeigen keine erwartbare Aufnahmequalität deines Teleskops. Die Fotos und Erfahrungsberichte von TonightPlan wurden nicht übernommen.</p></details><button data-act="sources" class="full-width space-top">Datenquellen & Datenschutz</button></section></div><p class="footer-note">Sternklar ${APP_VERSION} · Eigenständige Umsetzung, inspiriert von TonightPlan.</p>`;}
function bindMain(){const d=$('#night-date');if(d)d.addEventListener('change',()=>{if(d.value&&d.validity.valid)changeDate(d.value);});$('#active-scope')?.addEventListener('change',e=>{state.scope=e.target.value;persist();recalc();render();});$('#search-targets')?.addEventListener('input',e=>{filters.q=e.target.value;limit=36;updateResults();});$('#filter-direction')?.addEventListener('change',e=>{filters.direction=e.target.value;updateResults();});$('#filter-sort')?.addEventListener('change',e=>{filters.sort=e.target.value;updateResults();});$('#only-visible')?.addEventListener('change',e=>{filters.onlyVisible=e.target.checked;updateResults();});}
function changeDate(next){if(!/^\d{4}-\d{2}-\d{2}$/.test(next)||+next.slice(0,4)<1900||+next.slice(0,4)>2100)return;date=next;recalc();render();}
async function loadWeather(force=false){const key=`${state.location.lat},${state.location.lon}`;if(weatherLoading&&key===weatherKey)return;const seq=++generation;weatherKey=key;weatherLoading=true;weatherError='';if($('#weather-card'))$('#weather-card').innerHTML=weatherCard();try{const data=await weather(state.location,force);if(seq!==generation)return;weatherData=data;}catch(e){if(seq!==generation)return;weatherData=null;weatherError=navigator.onLine?'Wetter konnte nicht geladen werden. Prüfe die Verbindung und versuche es erneut.':'Offline: Für diesen Standort sind keine Wetterdaten gespeichert.';}finally{if(seq===generation){weatherLoading=false;if($('#weather-card'))$('#weather-card').innerHTML=weatherCard();if($('#week-forecast'))$('#week-forecast').innerHTML=weekHTML();}}}
function addPlan(id){const index=state.plan.findIndex(p=>p.id===id&&p.scope===state.scope);if(index>=0){state.plan.splice(index,1);toast('Aus dem Plan entfernt.');}else{state.plan.push({id,scope:state.scope,minutes:60});toast('Für 60 Minuten eingeplant.');}persist();render();if(dialogTarget)showTarget(dialogTarget);}
function advice(t){const list=[];if(t.emission)list.push(state.filter==='dual'?'Dualband passt zu diesem Emissionsziel und unterdrückt einen Teil des Himmelslichts.':'Ein Dualbandfilter kann bei diesem Emissionsziel helfen.');else if(t.group==='Galaxie'||t.type==='RfN')list.push('Breitbandziel: Ein Dualbandfilter würde viel Nutzsignal abschneiden. Ein dunkler Himmel ist besonders wertvoll.');else if(t.group==='Sternhaufen')list.push('Sternhaufen sind oft auch bei aufgehelltem Himmel lohnend. Achte auf runde, nicht ausgebrannte Sterne.');if(t.fit.ratio<1)list.push('Plane ein Mosaik oder wähle ein Setup mit größerem Bildfeld.');if(t.fit.ratio>12)list.push('Das Motiv ist sehr klein im Bild. Ein längeres Teleskop zeigt mehr Details.');if(t.minMoon<40)list.push(`Der Mond nähert sich im Aufnahmefenster bis auf etwa ${t.minMoon.toFixed(0)}°. Streulicht kann den Kontrast stark senken.`);if(t.hours<1)list.push('Das freie Aufnahmefenster ist kurz. Prüfe Hindernisse und beginne rechtzeitig.');return list;}
function showTarget(id){const t=results.find(t=>t.id===id);if(!t)return;dialogTarget=id;const comparison=scopes();dialog(t.id+' · '+t.group,`<p class="eyebrow">${esc(t.constellation)} · ${t.type==='PN'?'PLANETARISCHER NEBEL':esc(t.group)}</p><h2 class="detail-title">${esc(t.name)}</h2><div class="row wrap"><span class="pill ${grade(t.score)} pill-score">${t.score}/100 Eignung</span><span class="pill">${t.fit.label}</span><span class="pill">${t.major?t.major+'′ × '+t.minor+'′':'Größe unbekannt'}</span></div><div class="tool-row space-top"><button data-add="${esc(id)}" class="primary">${state.plan.some(p=>p.id===id&&p.scope===state.scope)?'✓ Im Plan':'+ Einplanen'}</button><button data-wish="${esc(id)}">${state.wish.includes(id)?'♥ Gemerkt':'♡ Merken'}</button><button data-capture="${esc(id)}">${state.captured[id]?'✓ Aufgenommen':'Aufnahme notieren'}</button></div><section class="panel space-top"><div class="panel-heading"><h3>Wann lohnt sich die Aufnahme?</h3><small>${Math.round(t.peak.alt)}° maximal</small></div>${curve(t,ctx,true)}<p><small>Mint: nutzbares Fenster · Gold gestrichelt: dein Horizont / Mindesthöhe</small></p>${t.windows.map(w=>`<p class="row spread"><strong>${time(w.start,state.location.tz)}–${time(w.end,state.location.tz)}</strong><span class="muted">${duration((w.end-w.start)/36e5)}</span></p>`).join('')||'<p class="muted">In dieser Nacht kein freies Aufnahmefenster.</p>'}</section><div class="detail-grid"><section class="panel"><h3>Passt es in dein Bild?</h3>${fovChart(t,comparison)}<p><small>Maßstäbliche Ausdehnung; keine Fotografie. Sensoren in Landschaftsorientierung dargestellt.</small></p></section><section class="panel"><h3>Für deine Aufnahme</h3>${advice(t).map(a=>`<p class="muted">${a}</p>`).join('')}<small>Koordinaten J2000: RA ${t.ra.toFixed(4)} h · Dec ${signed(t.dec.toFixed(3))}°<br>Helligkeit: ${t.mag??'unbekannt'} mag · Höhe ${Math.round(t.peak.alt)}° ${t.dir}</small></section></div><section class="panel"><h3>Surveybild zur Orientierung</h3><p class="muted">DSS2-Farbaufnahme · keine Vorschau der erreichbaren Bildqualität.</p><img id="survey-image" class="detail-image" alt="DSS2 Survey von ${esc(t.name)}" hidden><div class="tool-row"><button data-image="${esc(id)}">Surveybild laden</button><button data-finder="${esc(id)}">Aufsuchkarte</button><button data-share-target="${esc(id)}">Ziel teilen</button></div><p id="image-status" class="statusline">Bildabruf über CDS Strasbourg. Nur die Objektkoordinaten werden übertragen.</p></section>${state.captured[id]?`<section class="panel"><h3>Deine Aufnahme · ${esc(state.captured[id].date)}</h3><p style="white-space:pre-wrap">${esc(state.captured[id].note||'Keine Notiz gespeichert.')}</p><button data-capture="${esc(id)}">Notiz bearbeiten</button></section>`:''}`);}
function imageURL(t){const f=Math.min(12,Math.max(.15,(t.major||30)/60*1.4));return `https://alasky.cds.unistra.fr/hips-image-services/hips2fits?hips=CDS%2FP%2FDSS2%2Fcolor&width=720&height=480&fov=${f.toFixed(4)}&projection=TAN&coordsys=icrs&ra=${(t.ra*15).toFixed(6)}&dec=${t.dec.toFixed(6)}&format=jpg`;}
async function loadImage(id){const t=catalog.find(t=>t.id===id),img=$('#survey-image'),status=$('#image-status');status.textContent='Surveybild wird geladen …';img.onload=()=>{img.hidden=false;status.textContent='DSS2 · STScI / Caltech / AAO · bereitgestellt vom CDS.';};img.onerror=()=>{img.hidden=true;status.textContent='Das Bild ist derzeit nicht erreichbar. Koordinaten und Aufsuchkarte funktionieren weiterhin.';};img.src=imageURL(t);}
function showNightDetails(){dialog('Die Nacht im Detail',`<p>${esc(nightLabel())} · ${esc(state.location.name)}</p><div class="scroll-table"><table><tbody>${[['Sonnenuntergang',ctx.sunTimes.sunset],['Bürgerliche Dämmerung endet',ctx.sunTimes.civil],['Nautische Dämmerung endet',ctx.sunTimes.nautical],['Astronomische Dunkelheit beginnt',ctx.sunTimes.darkStart],['Astronomische Dunkelheit endet',ctx.sunTimes.darkEnd],['Sonnenaufgang',ctx.sunTimes.sunrise],['Mondaufgang',ctx.moonRise],['Monduntergang',ctx.moonSet]].map(([name,d])=>`<tr><th>${name}</th><td>${d?longDate(d,state.location.tz)+' · '+time(d,state.location.tz):'Kein Ereignis in dieser Nacht'}</td></tr>`).join('')}</tbody></table></div><p class="notice">Die Nacht zählt von lokalem Mittag bis zum nächsten Mittag. So gehören Aufnahmen nach Mitternacht weiterhin zum richtigen Abend. Alle Zeiten: ${esc(state.location.tz)}.</p><p>${phaseName()} · ${Math.round(ctx.illum*100)} % beleuchtet.</p>`);}
function weatherDetails(){const rows=nightRows(weatherData,ctx);dialog('Stundenwetter · '+state.location.name,rows.length?`<p class="muted">${esc(nightLabel())} · ${esc(state.location.tz)}</p>${weatherData.stale?'<div class="notice">Veraltete, gespeicherte Prognose. Aktueller Abruf fehlgeschlagen.</div>':''}<div class="scroll-table"><table><thead><tr><th>Zeit</th><th>Chancen</th><th>Wolken</th><th>Tief / mittel / hoch</th><th>Temperatur</th><th>Taupunkt</th><th>Wind / Böen</th><th>Regenrisiko</th><th>Regen</th><th>Sichtweite</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${time(r.d,state.location.tz)}</td><td><span class="pill ${grade(r.score)}">${r.score===null?'—':r.score+'/100'}</span></td><td>${r.cloud_cover??'—'} %</td><td>${r.cloud_cover_low??'—'} / ${r.cloud_cover_mid??'—'} / ${r.cloud_cover_high??'—'} %</td><td>${temp(r.temperature_2m)}</td><td>${temp(r.dew_point_2m)} ${r.temperature_2m-r.dew_point_2m<3?'· Tau möglich':''}</td><td>${wind(r.wind_speed_10m)} / ${wind(r.wind_gusts_10m)}</td><td>${r.precipitation_probability??'—'} %</td><td>${r.precipitation??'—'} mm</td><td>${r.visibility===null?'—':(r.visibility/(state.units==='imperial'?1609:1000)).toFixed(1)} ${state.units==='imperial'?'mi':'km'}</td></tr>`).join('')}</tbody></table></div><p class="notice">Seitlich wischen für alle Werte. „Chancen“ kombiniert Wolken, Regen, Böen, Taupunktabstand und Sichtweite. Kein Seeing-Modell. Wolkenschichten überlagern sich und werden nicht addiert.</p><small>Open-Meteo · Stand ${longDate(weatherData.at,state.location.tz)} ${time(weatherData.at,state.location.tz)}</small>`:'<p>Für diese Nacht stehen keine Stundenwerte zur Verfügung.</p><button data-act="weather-refresh">Wetter erneut abrufen</button>');}
function showSky(id){const t=id?results.find(t=>t.id===id):null;const initial=t?.peak.d||ctx.mid;dialog(t?'Aufsuchkarte · '+t.name:'Dein Himmel',`<div class="sky-controls"><label class="field full-width">Zeit in der Nacht<input id="sky-time" type="range" min="0" max="${Math.round((ctx.end-ctx.start)/6e5)}" value="${Math.round((initial-ctx.start)/6e5)}"></label><label class="row"><input id="sky-labels" type="checkbox" checked> Namen</label></div><div class="row wrap space-top"><label class="row"><input id="sky-lines" type="checkbox" checked> Sternbilder</label>${t?'<label class="field">Kartenausschnitt<select id="finder-fov"><option value="0">Ganzer Himmel</option><option value="5" selected>5° um das Ziel</option><option value="15">15° um das Ziel</option><option value="30">30° um das Ziel</option></select></label>':''}</div><div id="sky-surface"></div><p class="muted">Heller Sternkatalog bis 5 mag. Ganzhimmel: N oben, O rechts, Gold markiert Hindernisse. Zielausschnitt: N oben, O links, Gold zeigt den Sensorrahmen. Keine automatische Drehung mit dem Telefon.</p>`);const paint=()=>{const d=new Date(+ctx.start+Number($('#sky-time').value)*6e5);const field=Number($('#finder-fov')?.value||0);$('#sky-surface').innerHTML=t&&field?finderChart(t,stars,constellations,field,getScope(state),$('#sky-labels').checked,$('#sky-lines').checked):skyChart(stars,t?[t]:results.filter(t=>t.hours>0).slice(0,16),ctx,d,$('#sky-labels').checked,constellations,$('#sky-lines').checked);};$('#sky-time').addEventListener('input',paint);$('#sky-labels').addEventListener('change',paint);$('#sky-lines').addEventListener('change',paint);$('#finder-fov')?.addEventListener('change',paint);paint();}
function showEvents(){if(!eventCache)eventCache={events:events(ctx),meteors:meteorEvents(ctx,state.sky)};dialog('Dein Himmelskalender',`<p class="muted">Ab ${esc(date)} · ${esc(state.location.name)} · lokale Zeiten</p><h3>Meteorströme</h3><p><small>Typische jährliche Maxima; Zeitpunkte und Raten sind Näherungen. Ausbrüche sind nicht vorhergesagt.</small></p><div class="event-list">${eventCache.meteors.map(e=>`<article class="event"><div class="event-date">${longDate(e.peak,state.location.tz)}</div><div><h3>${e.name}</h3><p>${e.best?`Modellschätzung am Maximum: ~${Math.round(e.best.rate)} pro Stunde<br>Günstig ab ${time(e.best.d,state.location.tz)} · Radiant ${Math.round(e.best.alt)}°`:'Radiant / Dunkelheit an diesem Standort ungünstig'}</p><small>ZHR ${e.zhr} unter Idealbedingungen · ${e.speed} km/s</small></div></article>`).join('')}</div><h3 class="space-top">Mond, Planeten & Jahreszeiten</h3><div class="event-list">${eventCache.events.map(e=>`<article class="event"><div class="event-date">${longDate(e.d,state.location.tz)}<br>${time(e.d,state.location.tz)}</div><div><small>${e.kind}</small><h3>${e.name}</h3>${e.alt!==undefined?`<p>${e.alt>0?Math.round(e.alt)+'° über':'Unter'} dem lokalen Horizont zum Ereigniszeitpunkt</p>`:''}</div></article>`).join('')}</div><p class="notice">Mondbegegnungen sind nächtlich abgetastete Annäherungen, keine sekundengenauen Konjunktionen. Die Höhe beschreibt die Lage am Ereigniszeitpunkt, nicht automatisch dessen Beobachtbarkeit. Sonnenbeobachtung nur mit geeignetem Sonnenfilter.</p>`);}
function showLocation(){dialog('Wo möchtest du beobachten?',`<div class="tool-row"><button data-act="gps">⌖ Aktueller Standort</button><button data-act="show-map">Auf Karte wählen</button></div><label class="field space-top">Ort suchen<div class="row"><input id="city-query" type="search" placeholder="Stadt oder Ort" autocomplete="off"><button data-act="city-search">Suchen</button></div></label><div id="city-results" class="space-top"></div><div id="location-map" class="map hidden"></div><div class="field-grid space-top"><label class="field full">Name<input id="loc-name" value="${esc(state.location.name)}" maxlength="100"></label><label class="field">Breitengrad<input id="loc-lat" type="number" step="any" min="-90" max="90" value="${state.location.lat}"></label><label class="field">Längengrad<input id="loc-lon" type="number" step="any" min="-180" max="180" value="${state.location.lon}"></label><label class="field full">Zeitzone<input id="loc-tz" value="${esc(state.location.tz)}" placeholder="Europe/Berlin" list="timezones"><datalist id="timezones">${['Europe/Berlin','Europe/London','Europe/Paris','Atlantic/Canary','America/New_York','America/Los_Angeles','America/Santiago','Africa/Windhoek','Australia/Sydney','Pacific/Auckland','Asia/Tokyo','UTC'].map(z=>`<option value="${z}"></option>`).join('')}</datalist></label></div><p class="notice">Bei GPS, Karte oder manuellen Koordinaten die Zeitzone prüfen. Die Ortssuche trägt sie automatisch ein.</p><div class="tool-row"><button data-act="use-location" class="primary">Standort verwenden</button><button data-act="save-location">Als Beobachtungsplatz speichern</button></div><p id="loc-status" class="statusline" role="status"></p><h3 class="space-top">Gespeicherte Plätze</h3>${state.places.map((p,i)=>`<div class="saved-place"><button data-place="${i}">${esc(p.name)}<small>${p.lat.toFixed(3)}°, ${p.lon.toFixed(3)}° · ${esc(p.tz)}</small></button><button data-delete-place="${i}" aria-label="${esc(p.name)} entfernen">×</button></div>`).join('')||'<p class="muted">Speichere deinen Garten oder deinen nächsten Reiseort.</p>'}`);$('#city-query').addEventListener('keydown',e=>{if(e.key==='Enter')searchCity();});}
function readLocation(){const name=$('#loc-name').value.trim()||'Beobachtungsplatz',lat=Number($('#loc-lat').value),lon=Number($('#loc-lon').value),tz=$('#loc-tz').value.trim();if(!$('#loc-lat').value||!$('#loc-lon').value)throw new Error('Bitte beide Koordinaten eingeben.');const matching=[state.location,...state.places].find(p=>Math.abs(p.lat-lat)<.005&&Math.abs(p.lon-lon)<.005);return sanitizeLocation({name,lat,lon,tz,horizon:matching?.horizon||Array(8).fill(0)});}
function activateLocation(loc){state.location=sanitizeLocation(loc);state.onboarded=true;date=currentNight(loc.tz);persist();weatherData=null;weatherError='';recalc();close();render();loadWeather();toast('Standort übernommen. Die aktuelle Nacht wurde neu berechnet.');}
async function searchCity(){const q=$('#city-query').value.trim();if(q.length<2)return;const sequence=++searchSequence;$('#city-results').textContent='Orte werden gesucht …';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const r=await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(q)}&count=8&language=de&format=json`,{signal:controller.signal});if(!r.ok)throw new Error('Suche nicht erreichbar');const j=await r.json();if(sequence!==searchSequence||!$('#city-results'))return;const found=j.results||[];$('#city-results').innerHTML=found.length?found.map((p,i)=>`<button class="full-width" data-city="${i}" style="text-align:left;margin:4px 0">${esc(p.name)}<small class="sub">${esc(p.admin1||'')} · ${esc(p.country||'')} · ${esc(p.timezone||'Zeitzone prüfen')}</small></button>`).join(''):'Keine passenden Orte. Versuche einen anderen Namen oder trage Koordinaten ein.';$$('[data-city]').forEach(b=>b.addEventListener('click',()=>{const p=found[+b.dataset.city];$('#loc-name').value=p.name;$('#loc-lat').value=p.latitude;$('#loc-lon').value=p.longitude;$('#loc-tz').value=p.timezone||'UTC';$('#city-results').textContent='Ort ausgewählt. Mit „Standort verwenden“ bestätigen.';}));}catch{$('#city-results')&&($('#city-results').textContent='Ortssuche nicht erreichbar. Du kannst Koordinaten manuell eingeben.');}finally{clearTimeout(timer);}}
function gps(){if(!navigator.geolocation){$('#loc-status').textContent='GPS wird von diesem Browser nicht unterstützt.';return;}$('#loc-status').textContent='Standortfreigabe wird angefragt …';navigator.geolocation.getCurrentPosition(p=>{if(!$('#loc-lat'))return;$('#loc-lat').value=p.coords.latitude.toFixed(5);$('#loc-lon').value=p.coords.longitude.toFixed(5);$('#loc-name').value='Mein Standort';$('#loc-tz').value=Intl.DateTimeFormat().resolvedOptions().timeZone;$('#loc-status').textContent=`GPS übernommen (Genauigkeit etwa ${Math.round(p.coords.accuracy)} m). Zeitzone prüfen und Standort bestätigen.`;},e=>{if($('#loc-status'))$('#loc-status').textContent=e.code===1?'Standortfreigabe abgelehnt. Ortssuche oder Koordinaten funktionieren weiterhin.':'GPS nicht verfügbar. Bitte Ortssuche verwenden.';},{timeout:12000,maximumAge:120000,enableHighAccuracy:false});}
function showMap(){const el=$('#location-map');if(!globalThis.L){$('#loc-status').textContent='Karte nicht verfügbar. Bitte Koordinaten eingeben.';return;}el.classList.remove('hidden');if(el.dataset.ready)return;el.dataset.ready='yes';const map=L.map(el,{attributionControl:true}).setView([state.location.lat,state.location.lon],7);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>'}).addTo(map);let mark=L.circleMarker([state.location.lat,state.location.lon],{radius:8,color:'#9fe8d6'}).addTo(map);map.on('click',e=>{mark.setLatLng(e.latlng);$('#loc-lat').value=e.latlng.lat.toFixed(5);$('#loc-lon').value=e.latlng.lng.toFixed(5);$('#loc-name').value='Gewählter Kartenpunkt';$('#loc-status').textContent='Kartenpunkt gewählt. Bitte Name und Zeitzone prüfen.';});setTimeout(()=>map.invalidateSize(),50);}
function showHorizon(){dialog('Deinen Horizont freihalten',`<p class="muted">${esc(state.location.name)} · Wie hoch reichen Bäume, Häuser oder ein Dach? 0° bedeutet freie Sicht; 90° sperrt die Richtung.</p><div class="horizon-grid">${DIRS.map((d,i)=>`<label>${d}<output id="horizon-value-${i}">${state.location.horizon[i]}°</output><input type="range" min="0" max="90" step="5" value="${state.location.horizon[i]}" data-horizon="${i}" aria-label="Hindernishöhe ${d}"></label>`).join('')}</div><p class="notice">Zwischen den acht Richtungen wird die Hindernishöhe interpoliert. Zusätzlich gilt deine Mindesthöhe von ${state.minAltitude}°. Prüfe knappe Fenster vor Ort.</p><div class="tool-row"><button data-act="save-horizon" class="primary">Horizont speichern</button><button data-act="clear-horizon">Freier Rundumblick</button></div>`);$$('[data-horizon]').forEach(el=>el.addEventListener('input',()=>{$('#horizon-value-'+el.dataset.horizon).textContent=el.value+'°';}));}
function showCustomScope(){dialog('Dein eigenes Setup',`<form id="scope-form"><div class="field-grid"><label class="field full">Name<input id="scope-name" required maxlength="80" placeholder="z. B. Newton + Kamera"></label><label class="field">Brennweite (mm)<input id="scope-focal" type="number" min="1" max="50000" step="any" value="650" required></label><label class="field">Öffnung (mm)<input id="scope-aperture" type="number" min="1" max="10000" step="any" value="130" required></label><label class="field">Pixelgröße (µm)<input id="scope-pixel" type="number" min="0.1" max="100" step="any" value="2.9" required></label><label class="field">Sensorbreite (Pixel)<input id="scope-px" type="number" min="1" max="99999" value="3840" required></label><label class="field">Sensorhöhe (Pixel)<input id="scope-py" type="number" min="1" max="99999" value="2160" required></label></div><p id="fov-preview" class="notice"></p><button type="submit" class="primary full-width">Setup speichern</button></form>`);const values=()=>({focal:+$('#scope-focal').value,aperture:+$('#scope-aperture').value,pixel:+$('#scope-pixel').value,px:+$('#scope-px').value,py:+$('#scope-py').value});const preview=()=>{const f=fov(values());$('#fov-preview').textContent=Number.isFinite(f.w)?`Bildfeld: ${(f.w/60).toFixed(2)}° × ${(f.h/60).toFixed(2)}°`:'Bitte gültige Werte eintragen.';};$('#scope-form').addEventListener('input',preview);preview();$('#scope-form').addEventListener('submit',e=>{e.preventDefault();const s={...values(),id:'custom-'+Date.now(),name:$('#scope-name').value.trim()};if(!s.name)return;state.customScopes.push(s);state.scopes.push(s.id);state.scope=s.id;persist();recalc();close();render();toast('Setup gespeichert.');});}
function capture(id){const old=state.captured[id];dialog('Aufnahme · '+id,`<form id="capture-form"><label class="field">Aufnahmedatum<input id="capture-date" type="date" value="${old?.date||date}" required></label><label class="field space-top">Deine Notizen<textarea id="capture-note" rows="5" maxlength="4000" placeholder="Belichtungszeit, Filter, Ergebnis …">${esc(old?.note||'')}</textarea></label><div class="tool-row space-top"><button type="submit" class="primary">Speichern</button>${old?`<button type="button" data-unmark="${esc(id)}">Markierung entfernen</button>`:''}</div></form>`);$('#capture-form').addEventListener('submit',e=>{e.preventDefault();state.captured[id]={date:$('#capture-date').value,note:$('#capture-note').value};persist();render();showTarget(id);toast('Aufnahme gespeichert.');});}
function download(filename,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function showImport(){dialog('Deine Daten mitnehmen',`<p class="muted">Wähle eine Sternklar-Sicherungsdatei oder füge einen Übertragungscode ein. Vor dem Einlesen kannst du Zusammenführen oder Ersetzen wählen.</p><label class="field">Sicherungsdatei<input id="import-file" type="file" accept="application/json,.json"></label><label class="field space-top">Übertragungscode<textarea id="import-code" rows="4" placeholder="Code oder JSON einfügen"></textarea></label><button data-act="parse-import" class="primary space-top">Vorschau anzeigen</button><p id="import-error" class="statusline" role="status"></p>`);$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;if(f.size>2e6){$('#import-error').textContent='Die Datei ist zu groß (max. 2 MB).';return;}try{previewImport(JSON.parse(await f.text()));}catch(err){$('#import-error').textContent='Ungültige Datei: '+err.message;}});}
function previewImport(raw){const imported=validate(raw);dialog('Sicherung prüfen',`<p><strong>${esc(imported.location.name)}</strong> · ${imported.scopes.length} Teleskope</p><p>${imported.wish.length} gemerkte Ziele · ${Object.keys(imported.captured).length} Aufnahmen · ${imported.plan.length} geplante Aufnahmen · ${imported.places.length} Plätze</p><p class="notice">„Zusammenführen“ behält vorhandene Listen und ergänzt die Sicherung. Einstellungen kommen aus der Sicherung. „Ersetzen“ ersetzt die aktuellen Daten; vorher wird automatisch eine Sicherungsdatei angeboten.</p><div class="tool-row"><button id="merge-import" class="primary">Zusammenführen</button><button id="replace-import">Ersetzen</button></div>`);const apply=merge=>{if(!merge)download(`sternklar-vor-import-${date}.json`,exportData(state));state=merge?mergeState(state,imported):imported;state.onboarded=true;date=currentNight(state.location.tz);persist();recalc();weatherData=null;close();render();loadWeather();toast('Daten eingelesen.');};$('#merge-import').addEventListener('click',()=>apply(true));$('#replace-import').addEventListener('click',()=>apply(false));}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('In die Zwischenablage kopiert.');return true;}catch{return false;}}
function showShare(ids){const payload=sharePayload(state,date,ids),url=location.origin+location.pathname+'#share='+encodePayload(payload);dialog(ids.length===1?'Ziel teilen':'Deine Nacht teilen',`<p class="muted">Der Link enthält Datum, die gerundeten Standortkoordinaten (etwa 1 km), Horizont und ${ids.length} Ziele. Notizen und Aufnahmehistorie bleiben privat.</p><label class="field">Link<textarea id="share-link" rows="4" readonly>${esc(url)}</textarea></label><div class="tool-row space-top"><button id="share-native" class="primary">Teilen</button><button id="share-copy">Link kopieren</button></div>`);$('#share-copy').onclick=async()=>{if(!await copy(url)){$('#share-link').select();toast('Bitte den markierten Link manuell kopieren.');}};$('#share-native').onclick=async()=>{if(navigator.share){try{await navigator.share({title:'Sternklar · '+date,url});}catch(e){if(e.name!=='AbortError')toast('Teilen fehlgeschlagen. Du kannst den Link kopieren.');}}else if(!await copy(url))$('#share-link').select();};}
function showShared(data){let p;try{p=parseShared(data,catalog.map(t=>t.id));}catch(e){toast(e.message);return;}dialog('Ein Plan wurde mit dir geteilt',`<p><strong>${esc(p.location.name)}</strong> · Nacht vom ${esc(p.date)}</p><p>${p.ids.length} Ziele: ${p.ids.map(esc).join(', ')||'Nachtübersicht ohne Ziele'}</p><p class="muted">Übernimm Standort und Datum, um dieselbe Nacht zu sehen. Ziele werden deinem Plan hinzugefügt; bestehende Einträge bleiben erhalten.</p><button id="accept-shared" class="primary full-width">Geteilten Plan übernehmen</button>`);$('#accept-shared').onclick=()=>{state.location=p.location;date=p.date;const scope=state.scopes.includes(p.scope)?p.scope:state.scope;for(const id of p.ids)if(!state.plan.some(x=>x.id===id&&x.scope===scope))state.plan.push({id,scope,minutes:60});state.onboarded=true;persist();history.replaceState(null,'',location.pathname+'#plan');view='plan';weatherData=null;recalc();close();render();loadWeather();};}
function exportCalendar(){const scheduled=schedule().filter(p=>p.slot);if(!scheduled.length){toast('Es gibt noch keine Aufnahmen mit gültigem Zeitfenster.');return;}const stamp=d=>new Date(d).toISOString().replaceAll(/[-:]/g,'').replace(/\.\d{3}Z/,'Z');const clean=s=>String(s).replaceAll('\\','\\\\').replaceAll('\n','\\n').replaceAll(',','\\,').replaceAll(';','\\;');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Sternklar//Astroplaner//DE','CALSCALE:GREGORIAN',...scheduled.flatMap(p=>['BEGIN:VEVENT',`UID:${date}-${p.index}-${p.id}@sternklar.local`,`DTSTAMP:${stamp(new Date())}`,`DTSTART:${stamp(p.slot.start)}`,`DTEND:${stamp(p.slot.end)}`,`SUMMARY:${clean(p.target.name+' · '+getScope(state,p.scope).name)}`,`LOCATION:${clean(state.location.name)}`,`DESCRIPTION:${clean('Geplant mit Sternklar. Wetter und örtliche Sicht prüfen.')}`,'END:VEVENT']),'END:VCALENDAR'];const folded=lines.flatMap(line=>{const a=[];let chunk='';for(const c of line){if(new TextEncoder().encode(chunk+c).length>73){a.push(chunk);chunk=' '+c;}else chunk+=c;}a.push(chunk);return a;});download(`sternklar-${date}.ics`,folded.join('\r\n')+'\r\n','text/calendar;charset=utf-8');}
function autoPlan(){const additions=[];for(const scope of scopes()){const candidates=catalog.map(t=>analyze(t,ctx,scope,{...state,windowStart:sessionRange[0],windowEnd:sessionRange[1]})).filter(t=>t.hours>=1&&(!state.hideCaptured||!state.captured[t.id])).sort((a,b)=>b.score-a.score);const chosen=candidates.filter(t=>!additions.some(p=>p.id===t.id)).slice(0,3).sort((a,b)=>a.peak.d-b.peak.d);for(const t of chosen)if(!state.plan.some(p=>p.id===t.id&&p.scope===scope.id))additions.push({id:t.id,scope:scope.id,minutes:60});}state.plan.push(...additions);persist();render();toast(additions.length?`${additions.length} Aufnahmen ergänzt. Prüfe die verfügbaren Zeitfenster.`:'Keine weiteren passenden Ziele gefunden.');}
async function offlineImages(){const el=$('#offline-progress');if(!('caches'in window)){el.textContent='Dieser Browser unterstützt keinen Offline-Bildspeicher.';return;}const ids=[...new Set([...state.wish,...state.plan.map(p=>p.id)])];if(!ids.length){el.textContent='Merke zuerst Ziele oder füge sie deinem Plan hinzu.';return;}const cache=await caches.open('sternklar-images-v1');let ok=0,fail=0;for(const id of ids){const t=catalog.find(t=>t.id===id);if(!t)continue;try{const url=imageURL(t);if(!await cache.match(url)){const res=await fetch(url,{signal:AbortSignal.timeout(20000)});if(!res.ok)throw new Error();await cache.put(url,res);}ok++;}catch{fail++;}if(el.isConnected)el.textContent=`${ok} Bilder gespeichert · ${fail} nicht verfügbar · ${ids.length} Ziele`;}toast('Offline-Bildspeicherung abgeschlossen.');}
function showSources(){dialog('Quellen & Datenschutz',`<p>Sternklar berechnet Himmelspositionen lokal und benötigt kein Benutzerkonto. Keine Werbung und kein Tracking.</p><ul class="source-list"><li><a href="https://github.com/cosinekitty/astronomy" target="_blank" rel="noopener">Astronomy Engine – Don Cross</a>: Sonne, Mond, Planeten, Dämmerung, Präzession und Ereignisse (MIT).</li><li><a href="https://github.com/mattiaverga/OpenNGC" target="_blank" rel="noopener">OpenNGC – Mattia Verga und Mitwirkende</a>: Deep-Sky-Daten (CC BY-SA 4.0). Auswahl, deutsche Namen und zusätzliche Katalogzuordnungen wurden ergänzt. Der abgeleitete Katalog bleibt CC BY-SA 4.0.</li><li><a href="https://github.com/ofrohn/d3-celestial" target="_blank" rel="noopener">D3-Celestial / XHIP-Sternkatalog</a>: helle Sterne für die Orientierung (siehe mitgelieferte Lizenzhinweise).</li><li><a href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo</a>: Wetter und Ortssuche. Wetterdaten CC BY 4.0; kostenlose Schnittstelle für nichtkommerzielle Nutzung. Abruf mit auf 0,1° gerundeten Koordinaten.</li><li><a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>: optionaler Kartenhintergrund (ODbL).</li><li><a href="https://alasky.cds.unistra.fr/hips-image-services/hips2fits" target="_blank" rel="noopener">CDS HiPS2FITS / DSS2</a>: optionale Surveybilder (STScI, Caltech, AAO). Keine Bilder des TonightPlan-Autors übernommen.</li><li><a href="https://www.imo.net/resources/calendar/" target="_blank" rel="noopener">International Meteor Organization</a>: typische Radianten, Sonnenlängen und ZHR der jährlichen Meteorströme. Lokale Raten sind grobe Modellschätzungen.</li><li>Gerätedaten: Herstellerangaben von DWARFLAB, ZWO Seestar, Celestron und Vaonis; Sensororientierung kann variieren. Eigene Setups sind frei konfigurierbar.</li></ul><h3>Was verlässt dein Gerät?</h3><p class="muted">Wetterabfragen übermitteln gerundete Koordinaten, die Ortssuche den Suchbegriff. Karten und Bilder werden erst bei Nutzung vom jeweiligen Anbieter geladen. Dabei sehen diese Dienste die üblichen Verbindungsdaten wie die IP-Adresse. Teilen erzeugt einen Link mit gerundetem Standort. Sicherungen enthalten deine selbst eingegebenen Daten.</p><h3>Offline & Grenzen</h3><p class="muted">Die App, Kataloge und Berechnungen sind nach erfolgreicher Installation offline verfügbar. Wetter zeigt dann den letzten Abruf mit Zeitstempel. Offline-Speicher kann vom Betriebssystem entfernt werden; eine exportierte Sicherung schützt vor Datenverlust. Die App steuert keine Teleskope.</p><p class="muted">Unabhängige Umsetzung, funktional inspiriert von <a href="https://tonightplan.cosmiccaptures.com/" target="_blank" rel="noopener">TonightPlan</a>. Eigene Bewertung statt persönlicher Erfahrungsnoten. Stand der Recherche: 24. September 2026.</p>`);}
const actions={
 'prev-date':()=>changeDate(shiftDate(date,-1)),'next-date':()=>changeDate(shiftDate(date,1)),today:()=>changeDate(currentNight(state.location.tz)),
 'night-details':showNightDetails,'weather-details':weatherDetails,'weather-refresh':()=>loadWeather(true),'sky-chart':()=>showSky(),'all-targets':()=>{location.hash='explore';},
 changelog:()=>showChangelog(),
 'check-update':()=>checkForUpdates(),
 'raw-export':()=>download('sternklar-originaldaten.json',rawStoredData()),'restore-update':()=>{dialog('Update-Sicherung wiederherstellen',`<p>Der Stand vor dem letzten bestätigten Update ersetzt deine aktuellen Eingaben. Sichere neuere Änderungen zuvor über „Datei sichern“.</p><button id="confirm-restore" class="primary">Sicherung wiederherstellen</button>`);$('#confirm-restore').onclick=()=>{try{restoreCheckpoint();location.reload();}catch(e){toast(e.message);}};},
 setup:()=>{state.onboarded=true;persist();location.hash='settings';},location:showLocation,horizon:showHorizon,'custom-scope':showCustomScope,events:showEvents,sources:showSources,
 'session-window':showSessionWindow,'city-search':searchCity,gps,'show-map':showMap,'use-location':()=>{try{activateLocation(readLocation());}catch(e){$('#loc-status').textContent=e.message;}},
 'save-location':()=>{try{const p=readLocation();const i=state.places.findIndex(x=>Math.abs(x.lat-p.lat)<.0001&&Math.abs(x.lon-p.lon)<.0001);if(i>=0)state.places[i]=p;else state.places.push(p);persist();$('#loc-status').textContent='Beobachtungsplatz gespeichert.';}catch(e){$('#loc-status').textContent=e.message;}},
 'clear-horizon':()=>{$$('[data-horizon]').forEach(el=>{el.value=0;$('#horizon-value-'+el.dataset.horizon).textContent='0°';});},
 'save-horizon':()=>{state.location.horizon=$$('[data-horizon]').map(el=>Number(el.value));state.places=state.places.map(p=>Math.abs(p.lat-state.location.lat)<.005&&Math.abs(p.lon-state.location.lon)<.005?{...p,horizon:[...state.location.horizon]}:p);persist();recalc();close();render();toast('Horizont gespeichert.');},
 filters:()=>{dialog('Ziele eingrenzen',`<label class="field">Katalog<select id="extra-catalogue"><option value="">Alle Kataloge</option>${['Messier','Caldwell','Andere'].map(c=>`<option ${filters.catalogue===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field space-top">Mindest-Eignung<select id="extra-impact"><option value="0">Alle</option><option value="55" ${filters.impact===55?'selected':''}>Lohnend · ab 55 Punkten</option><option value="75" ${filters.impact===75?'selected':''}>Beste Chancen · ab 75 Punkten</option></select></label><button id="apply-filters" class="primary full-width space-top">Filter anwenden</button>`);$('#apply-filters').onclick=()=>{filters.catalogue=$('#extra-catalogue').value;filters.impact=Number($('#extra-impact').value);close();render();};},
 'reset-filters':()=>{filters={q:'',group:'Alle',direction:'',catalogue:'',sort:'score',mosaic:false,easy:false,wish:false,captured:false,onlyVisible:false,impact:0};render();},'load-more':()=>{limit+=36;updateResults();},
 'auto-plan':autoPlan,'sort-plan':()=>{const lookup=new Map(results.map(t=>[t.id,t]));state.plan.sort((a,b)=>(lookup.get(a.id)?.windows[0]?.start||Infinity)-(lookup.get(b.id)?.windows[0]?.start||Infinity));persist();render();},'print-plan':()=>window.print(),'export-calendar':exportCalendar,
 'share-plan':()=>showShare([...new Set(state.plan.map(p=>p.id))]),'export-data':()=>download(`sternklar-sicherung-${date}.json`,exportData(state)),
 'export-code':()=>{const code=encodePayload(state);dialog('Übertragungscode',`<p class="muted">Dieser Code enthält alle deine Sternklar-Daten. Auf dem neuen Gerät unter „Daten einlesen“ einfügen.</p><textarea id="transfer-code" rows="5" readonly>${code}</textarea><button id="copy-code" class="primary space-top full-width">Code kopieren</button>`);$('#copy-code').onclick=async()=>{if(!await copy(code)){$('#transfer-code').select();toast('Bitte den Code manuell kopieren.');}};},
 'import-data':showImport,'parse-import':()=>{try{const value=$('#import-code').value.trim();previewImport(value.startsWith('{')?JSON.parse(value):decodePayload(value));}catch(e){$('#import-error').textContent=e.message;}},
 'offline-images':offlineImages,'offline-status':async()=>{const controlled=!!navigator.serviceWorker?.controller,keys='caches'in window?await caches.keys():[];const has=keys.some(k=>k.startsWith('sternklar-shell'));dialog('Offline-Verfügbarkeit',`<p>${has&&controlled?'✓ App, Katalog und Himmelsberechnungen sind für offline gespeichert.':has?'Die App ist gespeichert. Öffne sie einmal neu, um den Offline-Betrieb zu aktivieren.':'Der Offline-Speicher ist noch nicht bereit. Öffne die App über HTTPS und warte auf den ersten vollständigen Ladevorgang.'}</p><p class="muted">Wetter bleibt nur als zuletzt geladene Prognose verfügbar. Surveybilder kannst du für gemerkte oder geplante Ziele separat sichern.</p>`);}
};
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;try{if(el.dataset.act){const r=actions[el.dataset.act]?.();if(r?.catch)r.catch(err=>toast('Aktion fehlgeschlagen: '+err.message));}else if(el.dataset.target)showTarget(el.dataset.target);else if(el.dataset.add)addPlan(el.dataset.add);else if(el.dataset.group){filters.group=el.dataset.group;limit=36;render();}else if(el.dataset.filter){filters[el.dataset.filter]=!filters[el.dataset.filter];render();}else if(el.dataset.date)changeDate(el.dataset.date);else if(el.dataset.wish){const id=el.dataset.wish;state.wish=state.wish.includes(id)?state.wish.filter(x=>x!==id):[...state.wish,id];persist();render();showTarget(id);}else if(el.dataset.capture)capture(el.dataset.capture);else if(el.dataset.unmark){delete state.captured[el.dataset.unmark];persist();render();showTarget(el.dataset.unmark);}else if(el.dataset.image)loadImage(el.dataset.image);else if(el.dataset.finder)showSky(el.dataset.finder);else if(el.dataset.shareTarget)showShare([el.dataset.shareTarget]);else if(el.dataset.removePlan!==undefined){state.plan.splice(+el.dataset.removePlan,1);persist();render();}else if(el.dataset.place!==undefined)activateLocation(state.places[+el.dataset.place]);else if(el.dataset.deletePlace!==undefined){const removed=state.places.splice(+el.dataset.deletePlace,1)[0];persist();showLocation();toast(removed.name+' entfernt.');}}catch(err){toast('Bitte prüfe deine Eingabe: '+err.message);}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.setting){const key=el.dataset.setting;state[key]=el.type==='checkbox'?el.checked:['sky','minAltitude','textSize'].includes(key)?Number(el.value):el.value;state.minAltitude=clamp(state.minAltitude,0,85);persist();recalc();render();}else if(el.dataset.scopeToggle){const id=el.dataset.scopeToggle;if(el.checked)state.scopes.push(id);else if(state.scopes.length>1)state.scopes=state.scopes.filter(x=>x!==id);else{el.checked=true;toast('Mindestens ein Teleskop muss ausgewählt sein.');return;}if(!state.scopes.includes(state.scope))state.scope=state.scopes[0];persist();recalc();render();}else if(el.dataset.planScope!==undefined){state.plan[+el.dataset.planScope].scope=el.value;persist();render();}else if(el.dataset.planDuration!==undefined){state.plan[+el.dataset.planDuration].minutes=clamp(Number(el.value)||60,10,600);persist();render();}});
$('#close-dialog').onclick=close;$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});$('#dialog').addEventListener('close',()=>{dialogTarget=null;});$('#night-mode').onclick=()=>{state.redlight=!state.redlight;persist();applyTheme();};$('#location-button').onclick=showLocation;
function route(){const hash=location.hash.slice(1);if(hash.startsWith('share=')){if(catalog.length){try{showShared(decodePayload(hash.slice(6)));}catch{toast('Dieser Planlink ist ungültig.');}}return;}view=['tonight','explore','plan','settings'].includes(hash)?hash:'tonight';if(catalog.length){render();window.scrollTo({top:0,behavior:'instant'});}}
window.addEventListener('hashchange',route);window.addEventListener('online',()=>{updateChrome();loadWeather();});window.addEventListener('offline',updateChrome);
function showSessionWindow(){const max=ctx.samples.length;dialog('Wann hast du Zeit?',`<p class="muted">Grenze die Suche auf einen Teil der Nacht ein. Sichtfenster und Aufnahmeplan passen sich an.</p><label class="field">Frühester Start<input id="session-start" type="range" min="0" max="${max}" value="${Math.round(sessionRange[0]*max)}"></label><label class="field space-top">Spätestes Ende<input id="session-end" type="range" min="0" max="${max}" value="${Math.round(sessionRange[1]*max)}"></label><p id="session-label" class="notice"></p><div class="tool-row"><button id="session-apply" class="primary">Zeitfenster anwenden</button><button id="session-reset">Ganze Nacht</button></div>`);const preview=()=>{$('#session-label').textContent=time(new Date(+ctx.start+Number($('#session-start').value)*ctx.step),state.location.tz)+' – '+time(new Date(+ctx.start+Number($('#session-end').value)*ctx.step),state.location.tz);};$('#session-start').oninput=preview;$('#session-end').oninput=preview;preview();$('#session-apply').onclick=()=>{const a=Number($('#session-start').value),b=Number($('#session-end').value);if(b<=a){toast('Das Ende muss nach dem Start liegen.');return;}sessionRange=[a/max,b/max];recalc();close();render();toast('Aufnahmezeit berücksichtigt.');};$('#session-reset').onclick=()=>{sessionRange=[0,1];recalc();close();render();};}
function showChangelog(entries=RELEASES,afterUpdate=false){
 dialog(afterUpdate?'Was ist neu?':'Versionshistorie',`<p class="muted">${afterUpdate?'Sternklar wurde aktualisiert. Deine gespeicherten Daten bleiben erhalten.':'Deine installierte Version: '+APP_VERSION}</p>${entries.map(r=>`<section class="release-entry"><p class="eyebrow">VERSION ${esc(r.version)}</p><h3>${esc(r.title)}</h3><ul>${r.changes.map(c=>`<li>${esc(c)}</li>`).join('')}</ul></section>`).join('')}<button id="changelog-done" class="primary full-width">${afterUpdate?'Alles klar':'Schließen'}</button>`);
 $('#changelog-done').onclick=close;
 if(afterUpdate)$('#dialog').addEventListener('close',()=>acknowledgeRelease(localStorage),{once:true});
}
function offerChangelog(){
 let entries;try{entries=unseenReleases(localStorage);}catch{return;}
 if(!entries.length)return;
 if($('#dialog').open){$('#dialog').addEventListener('close',()=>setTimeout(()=>offerChangelog(),0),{once:true});return;}
 showChangelog(entries,true);
}
async function init(){try{[catalog,stars,constellations]=await Promise.all(['data/catalog.json','data/stars.json','data/constellations.json'].map(async p=>{const r=await fetch(p);if(!r.ok)throw new Error('Katalog nicht verfügbar');return r.json();}));if(!globalThis.Astronomy)throw new Error('Astronomie-Bibliothek konnte nicht geladen werden');state.plan=state.plan.filter(p=>catalog.some(t=>t.id===p.id));recalc();route();if(location.hash.startsWith('#share='))render();loadWeather();if(!import.meta.env?.DEV)setupUpdates();offerChangelog();if(storageIssue){const warning=document.createElement('aside');warning.className='notice';warning.setAttribute('role','alert');warning.textContent=storageIssue;document.querySelector('.topbar').after(warning);}}catch(e){$('#main').innerHTML=`<div class="empty"><h1>Der Himmel lädt noch nicht.</h1><p>${esc(e.message)}</p><button id="retry-init">Erneut versuchen</button></div>`;$('#retry-init').onclick=()=>location.reload();}}
if(import.meta.env?.DEV&&'serviceWorker'in navigator){navigator.serviceWorker.getRegistrations().then(rs=>rs.forEach(r=>r.unregister()));}
applyTheme();init();
